-- Read-only schema, permissions and aggregate compatibility checks. No record contents.
BEGIN TRANSACTION READ ONLY;
SELECT json_build_object(
 'table',(SELECT json_build_object('owner',pg_get_userbyid(relowner),'rls',relrowsecurity) FROM pg_class WHERE oid='public.properties'::regclass),
 'columns',(SELECT json_agg(json_build_object('column',column_name,'type',data_type,'udt',udt_name,'nullable',is_nullable,'default',column_default,'precision',numeric_precision,'scale',numeric_scale) ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name='properties'),
 'constraints',(SELECT json_agg(json_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conrelid::regclass::text,conname) FROM pg_constraint WHERE conrelid='public.properties'::regclass OR confrelid='public.properties'::regclass),
 'policies',(SELECT json_agg(json_build_object('name',policyname,'roles',roles,'command',cmd,'using',qual,'check',with_check) ORDER BY policyname) FROM pg_policies WHERE schemaname='public' AND tablename='properties'),
 'triggers',(SELECT json_agg(json_build_object('table',t.tgrelid::regclass::text,'name',t.tgname,'function',p.proname,'definition_md5',md5(pg_get_triggerdef(t.oid)),'body_md5',md5(p.prosrc)) ORDER BY t.tgrelid::regclass::text,t.tgname) FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE NOT t.tgisinternal AND t.tgrelid IN ('public.properties'::regclass,'public.property_images'::regclass,'public.property_floor_plans'::regclass,'public.property_features'::regclass,'public.property_amenities'::regclass,'public.viewing_requests'::regclass,'public.enquiries'::regclass)),
 'grants',(SELECT json_agg(json_build_object('role',grantee,'privilege',privilege_type) ORDER BY grantee,privilege_type) FROM information_schema.table_privileges WHERE table_schema='public' AND table_name='properties' AND grantee IN ('PUBLIC','anon','authenticated','service_role')),
 'role_permissions',(SELECT json_agg(json_build_object('role',r.name,'permission',p.name) ORDER BY r.name,p.name) FROM public.role_permissions rp JOIN public.roles r ON r.id=rp.role_id JOIN public.permissions p ON p.id=rp.permission_id WHERE p.name IN ('properties.view','properties.manage')),
 'legacy_aggregates',(SELECT json_build_object('rented_rows_exist',coalesce(bool_or(status='rented'),false),'negative_numeric_values_exist',coalesce(bool_or(price<0 OR bedrooms<0 OR bathrooms<0 OR floor_area<0 OR land_area<0),false),'title_max',coalesce(max(char_length(title)),0),'slug_max',coalesce(max(char_length(slug)),0),'description_max',coalesce(max(char_length(description)),0),'property_type_max',coalesce(max(char_length(property_type)),0),'listing_type_max',coalesce(max(char_length(listing_type)),0),'location_max',coalesce(max(char_length(location)),0),'address_max',coalesce(max(char_length(address)),0),'city_max',coalesce(max(char_length(city)),0),'region_max',coalesce(max(char_length(region)),0)) FROM public.properties),
 'last_migration',(SELECT max(version) FROM supabase_migrations.schema_migrations)
) AS evidence;
COMMIT;
